#include "traffic/Demo.hpp"
#include <iostream>
#include <set>
#include <algorithm>
using namespace traffic;
int main(int argc,char**argv){try{if(argc<4)throw std::runtime_error("map_network_audit MAP NODES METERS_PER_PIXEL [SMOKE_DESTINATION_NODE]");auto map=Map::fromPng(argv[1],std::stod(argv[3]));auto graph=NodeGraph::load(argv[2]);auto compiled=compileRoads(graph);validateRoadMask(compiled.lanes,map);std::set<int> reachable;for(std::size_t source=0;source<graph.nodes.size();++source)if(graph.nodes[source].spawn){std::vector<int> todo;std::vector<bool> seen(compiled.lanes.size());for(std::size_t i=0;i<compiled.originNodes.size();++i)if(compiled.originNodes[i]==static_cast<int>(source)){todo.push_back(i);seen[i]=true;}for(std::size_t i=0;i<todo.size();++i){const auto& l=compiled.lanes[todo[i]];if(l.destination && !(graph.nodes[source].excludeOwnDestination && l.destinationNode==static_cast<int>(source)))reachable.insert(l.destinationNode);for(int n:l.successors)if(!seen[n]){seen[n]=true;todo.push_back(n);}}}for(std::size_t i=0;i<graph.nodes.size();++i)if(graph.nodes[i].destination)std::cout<<"destination "<<i<<": "<<(reachable.count(i)?"reachable":"UNREACHABLE")<<'\n';
if(argc>4){int destination=std::stoi(argv[4]),entry=-1,sink=-1;for(std::size_t i=0;i<compiled.lanes.size();++i){const auto& l=compiled.lanes[i];if(l.roadGroup>=0 && l.sourceNode==0 && graph.nodes[0].spawn)entry=i;if(l.destinationNode==destination && l.destination && l.roadGroup>=0)sink=i;}if(entry<0 || sink<0)throw std::runtime_error("smoke route unavailable");Simulation s(std::move(map),42);s.setLanes(compiled.lanes);s.setTrafficFlowSettings({true,true,.4,.15});s.setStuckVehicleSettings({false,30});s.setProfile(VehicleKind::Motorbike,{{2,0},{.7,0},{.3,0},{6,0,2,0},1});s.loadTrafficLights(std::string(argv[2])+".signals");if(!s.spawnOnLane(entry,VehicleKind::Motorbike,sink))throw std::runtime_error("smoke insertion failed");for(int i=0;i<12000 && !s.entities().empty();++i)s.tick(.01);if(s.completed()!=1)throw std::runtime_error("smoke trip did not complete");std::cout<<"Source 0 -> destination "<<destination<<" completed with saved signals\n";}
return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
